const formMigrationKey = 'genesys-aqm-v03b-form-seeded'
const policiesStorage = 'genesys-aqm-v02-policies'
const time = (value: string) => new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit' }).format(new Date(value))
const date = (value: string) => new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value))
const pct = (value: number) => `${Math.round(value * 100)}%`
const icon: Record<Page, string> = { evaluate: '◈', conversations: '☷', forms: '▤', policies: '◇', automation: '◌', history: '◷', analytics: '▥', settings: '⚙' }
function readStore<T>(key: string, fallback: T): T { try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback } catch { return fallback } }
function migrateForms(forms: EvaluationForm[]): EvaluationForm[] {
  try { if (!localStorage.getItem(formMigrationKey)) { localStorage.setItem(formMigrationKey, '1'); return forms.some(form => form.id === genesysCustomerServiceForm.id) ? forms : [...forms, structuredClone(genesysCustomerServiceForm)] } } catch { /* Browser storage may be unavailable. */ }
  return forms
}
function readForms(): EvaluationForm[] {
  const stored = readStore<EvaluationForm[] | null>(formsStorage, null)
  if (Array.isArray(stored) && stored.length) return migrateForms(stored)
  try {
    const raw = localStorage.getItem('genesys-aqm-scorecard')
    if (raw) {
      const card = JSON.parse(raw) as Scorecard
      if (validateScorecard(card).length === 0) return migrateForms([{id:card.id,name:card.title,description:'Migrated editable scorecard from V0.1.',version:card.version,enabled:true,questions:card.items,scoring:{yesThreshold:card.threshold,passScore:.7,criticalQuestionIds:[]}},...seedForms])
    }
  } catch { /* use seed forms */ }
  return migrateForms(seedForms)
}
function readPolicies(): InteractionPolicy[] {
  const stored=readStore<InteractionPolicy[] | null>(policiesStorage,null)
  if(!Array.isArray(stored)) return seedPolicies.map(p=>({...p,version:1}))
  const demo=seedPolicies.find(p=>p.id==='sample_monitoring')!
  return (stored.some(p=>p.id===demo.id)?stored:[...stored,structuredClone(demo)]).map(p=>({...p,version:p.version??1}))
}
function useKey() { const [key, setKey] = useState(() => sessionStorage.getItem(keyStorage) ?? ''); return { key, save:(value:string) => { sessionStorage.setItem(keyStorage,value.trim()); setKey(value.trim()) }, clear:() => { sessionStorage.removeItem(keyStorage); setKey('') } } }
